def main():
    print(f"Generando el benchmark completo con {len(TOTAL_100_CORES)} núcleos técnicos únicos (100/100)...")
    os.makedirs("data", exist_ok=True)
    ruta_salida = "data/arca_symbolic_benchmark_extended.jsonl"
    
    with open(ruta_salida, "w", encoding="utf-8") as f:
        for c in TOTAL_100_CORES:
            f.write(json.dumps(c, ensure_ascii=False) + "\n")

    print(f"[OK] Dataset maestro de 100 núcleos guardado exitosamente en: {ruta_salida}")

if __name__ == "__main__":
    main()
